  # Defines the Neon SDK type.
  class Neon
    attr_reader :project, :api_key, :operation, :data_api, :auth_legacy, :auth, :branch, :realtime,
                :endpoint, :consumption, :organizations, :region, :users, :snapshot, :buckets,
                :storage, :ai_gateway, :logs, :credentials, :functions

    SUB_NAMESPACES = {
      project: ProjectNamespace,
      api_key: ApiKeyNamespace,
      operation: OperationNamespace,
      data_api: DataApiNamespace,
      auth_legacy: AuthLegacyNamespace,
      auth: AuthNamespace,
      branch: BranchNamespace,
      realtime: RealtimeNamespace,
      endpoint: EndpointNamespace,
      consumption: ConsumptionNamespace,
      organizations: OrganizationsNamespace,
      region: RegionNamespace,
      users: UsersNamespace,
      snapshot: SnapshotNamespace,
      buckets: BucketsNamespace,
      storage: StorageNamespace,
      ai_gateway: AiGatewayNamespace,
      logs: LogsNamespace,
      credentials: CredentialsNamespace,
      functions: FunctionsNamespace
    }.freeze
    private_constant :SUB_NAMESPACES

    def initialize(config)
      @config = config
      SUB_NAMESPACES.each do |accessor, namespace|
        instance_variable_set(:"@#{accessor}", namespace.new(config))
      end
    end

    # Turns SDK logging on and configures it. Logging is OFF by default — this
    # SDK reports nothing until you call this (or construct the client with a
    # config whose logging is enabled). Reports go to the endpoint this build was
    # generated with, or to the endpoint you pass; with neither, nothing is sent.
    # Pass enabled: false to turn logging back off.
    def set_logging_config(**fields)
      logging = (@config.logging ||= LoggingConfig.new)
      # Opting in IS the point of this call, so enabled flips to true — the
      # keyword loop below runs after, so an explicit enabled: false wins.
      logging.enabled = true
      fields.each do |key, value|
        setter = :"#{key}="
        raise ArgumentError, "LoggingConfig has no field #{key}" unless logging.respond_to?(setter)

        logging.public_send(setter, value)
      end
      logging
    end
  end
end
